# --- 서블릿 API 로 읽는다 ---

@GetMapping("/servlet-api")
@ResponseBody
public String servletApi(HttpServletRequest request, Authentication auth) {
    System.out.println(">>> class          = " + request.getClass().getSimpleName());
    System.out.println(">>> getUserPrincipal = " + request.getUserPrincipal());
    System.out.println(">>> getAuthentication= " + auth);
    System.out.println(">>> isUserInRole(USER)  = " + request.isUserInRole("USER"));
    System.out.println(">>> isUserInRole(ROLE_USER) = "
            + request.isUserInRole("ROLE_USER"));
    return "ok";
}

#   로그인한 채로
$ curl -s -b user.txt localhost:8080/servlet-api

>>> class          = Servlet3SecurityContextHolderAwareRequestWrapper
>>> getUserPrincipal = UsernamePasswordAuthenticationToken [Principal=...]
>>> getAuthentication= UsernamePasswordAuthenticationToken [Principal=...]
>>> isUserInRole(USER)  = true
>>> isUserInRole(ROLE_USER) = false

#   래퍼로 바뀌어 있다

#   isUserInRole 이 ROLE_ 을 붙인다

#   ROLE_USER 를 넘기면 ROLE_ROLE_USER 를 찾는다

#   7.7절과 같은 함정이다

#   로그인 안 한 채로
$ curl -s localhost:8080/servlet-api

>>> getUserPrincipal = null
>>> getAuthentication= AnonymousAuthenticationToken [Principal=anonymousUser]

#   하나는 null 이고 하나는 아니다

#   3.7절에서 본 그 차이다

#   서블릿 규격이 그렇게 정했다

# --- 필터를 꺼 본다 ---

http.servletApi(s -> s.disable());

$ ./gradlew bootRun 2>&1 | grep "Will secure" | tr ',' '\n' \
    | grep -c SecurityContextHolderAware
0

$ curl -s -b user.txt localhost:8080/servlet-api

>>> class          = ApplicationHttpRequest
>>> getUserPrincipal = null
>>> getAuthentication= UsernamePasswordAuthenticationToken [Principal=...]
>>> isUserInRole(USER)  = false

#   로그인했는데 null 이다

#   스프링 API 는 그대로 산다

#   서블릿 API 만 죽는다

#   JSP 의 <sec:authorize> 나 옛 필터가 여기서 깨진다

#   에러도 없다

# --- request.login 을 써 본다 ---

http.servletApi(withDefaults());     // 다시 켠다

@PostMapping("/api/login")
@ResponseBody
public String login(HttpServletRequest request,
        @RequestParam String email, @RequestParam String password)
        throws ServletException {
    request.login(email, password);
    System.out.println(">>> after login = "
            + SecurityContextHolder.getContext().getAuthentication());
    return "ok";
}

