void 서블릿_api_와_스프링_api_가_같다() throws Exception {
    mockMvc.perform(get("/servlet-api"))
            .andExpect(status().isOk());
}

@Test
void 익명이면_getUserPrincipal_이_null() throws Exception {
    mockMvc.perform(get("/servlet-api").with(anonymous()))
            .andExpect(status().isOk());
}

